267→        let temp = TempDir::new().unwrap();
268→        let store = CacheStore::new(temp.path());
269→        let git_dir = temp.path().join("git");
270→        let revalidator = CacheRevalidator::new(&store, git_dir);
271→
272→        let mut entry = store
273→            .store("http:test", "template", "old content", 0)
274→            .unwrap();
275→        entry.metadata.etag = Some("\"etag-v1\"".to_string());
276→        store.update(&entry).unwrap();
277→
278→        revalidator
279→            .revalidate_etag(&server.url("/template.yml"), &mut entry, 3600)
280→            .unwrap();
281→
282→        // Verify content on disk is updated
283→        let content = store.read_content(&entry).unwrap();
284→        assert_eq!(content, "updated content on disk");
285→    }
286→}
