 29→/// Maximum total execution attempts per step (auto-retries + manual retries).
 30→/// Prevents infinite loops when the recovery prompt always returns "retry"
 31→/// (e.g., in test environments with MockUI).
 32→const MAX_STEP_ATTEMPTS: u32 = 100;
 33→
 34→/// Progress events emitted during workflow execution.
 35→#[derive(Debug)]
 36→pub enum RunProgress<'a> {
 37→    /// A step is about to start.
 38→    StepStarting {
 39→        name: &'a str,
 40→        index: usize,
 41→        total: usize,
 42→    },
 43→    /// A step finished.
 44→    StepFinished {
 45→        name: &'a str,
 46→        result: &'a StepResult,
 47→    },
 48→    /// A step was skipped.
 49→    StepSkipped { name: &'a str },
 50→}
 51→
 52→/// Orchestrates the execution of a workflow.
 53→pub struct WorkflowRunner<'a> {
 54→    config: &'a BivvyConfig,
 55→    steps: HashMap<String, ResolvedStep>,
 56→}
 57→
 58→/// Result of running a workflow.
 59→#[derive(Debug)]
 60→pub struct WorkflowResult {
 61→    /// Workflow name.
 62→    pub workflow: String,
 63→    /// Results from each executed step.
 64→    pub steps: Vec<StepResult>,
 65→    /// Names of skipped steps.
 66→    pub skipped: Vec<String>,
 67→    /// Total duration.
 68→    pub duration: Duration,
 69→    /// Whether all steps succeeded.
 70→    pub success: bool,
 71→    /// Whether the workflow was aborted by the user during recovery.
 72→    pub aborted: bool,
 73→}
 74→
 75→/// Options for running a workflow.
 76→#[derive(Debug, Default)]
 77→pub struct RunOptions {
 78→    /// Workflow name (defaults to "default").
 79→    pub workflow: Option<String>,
 80→    /// Only run these steps.
 81→    pub only: HashSet<String>,
 82→    /// Skip these steps.
 83→    pub skip: HashSet<String>,
 84→    /// How to handle skipped step dependencies.
 85→    pub skip_behavior: SkipBehavior,
 86→    /// Force re-run these steps even if complete.
 87→    pub force: HashSet<String>,
 88→    /// Dry run mode.
 89→    pub dry_run: bool,
 90→    /// Requirements that are provided by the environment and should skip gap checks.
 91→    pub provided_requirements: HashSet<String>,
 92→    /// Active environment name for only_environments filtering.
 93→    pub active_environment: Option<String>,
 94→}
 95→
 96→impl<'a> WorkflowRunner<'a> {
 97→    /// Create a new workflow runner.
 98→    pub fn new(config: &'a BivvyConfig, steps: HashMap<String, ResolvedStep>) -> Self {
 99→        Self { config, steps }
100→    }
101→
102→    /// Run the specified workflow.
103→    pub fn run(
104→        &self,
105→        options: &RunOptions,
106→        context: &InterpolationContext,
107→        global_env: &HashMap<String, String>,
108→        project_root: &Path,
109→    ) -> Result<WorkflowResult> {
110→        self.run_with_progress(options, context, global_env, project_root, None, |_| {})
111→    }
112→
113→    /// Run the specified workflow with a progress callback.
114→    pub fn run_with_progress(
115→        &self,
116→        options: &RunOptions,
117→        context: &InterpolationContext,
118→        global_env: &HashMap<String, String>,
119→        project_root: &Path,
120→        mut gap_checker: Option<&mut GapChecker<'_>>,
121→        mut on_progress: impl FnMut(RunProgress<'_>),
122→    ) -> Result<WorkflowResult> {
123→        let start = Instant::now();
124→        let workflow_name = options.workflow.as_deref().unwrap_or("default");
125→
126→        // Build dependency graph
127→        let graph = self.build_graph(workflow_name)?;
128→
129→        // Compute skips
130→        let skipped = graph.compute_skips(&options.skip, options.skip_behavior);
131→
132→        // Get execution order
133→        let order = graph.topological_order()?;
134→
135→        // Filter by only_environments and --only/--skip
136→        let mut env_skipped: Vec<String> = Vec::new();
137→        let steps_to_run: Vec<_> = order
138→            .iter()
139→            .filter(|s| !skipped.contains(*s))
140→            .filter(|s| options.only.is_empty() || options.only.contains(*s))
141→            .filter(|s| {
142→                if let Some(step) = self.steps.get(*s) {
143→                    if !step.only_environments.is_empty() {
144→                        if let Some(ref active_env) = options.active_environment {
145→                            if !step.only_environments.iter().any(|e| e == active_env) {
146→                                env_skipped.push(s.to_string());
147→                                return false;
148→                            }
149→                        }
150→                    }

  1→//! Remote configuration fetching.
  2→//!
  3→//! This module provides functionality for fetching configuration files
  4→//! from remote URLs.
  5→
  6→use anyhow::{anyhow, Context, Result};
  7→use std::collections::HashMap;
  8→use std::path::PathBuf;
  9→use std::time::Duration;
 10→
 11→/// Fetches remote configuration files with caching.
 12→///
 13→/// # Example
 14→///
 15→/// ```no_run
 16→/// use bivvy::config::RemoteFetcher;
 17→/// use std::time::Duration;
 18→///
 19→/// let fetcher = RemoteFetcher::new(Duration::from_secs(30));
 20→///
 21→/// // Fetch a remote config file
 22→/// let content = fetcher.fetch("https://example.com/config.yml").unwrap();
 23→/// ```
 24→pub struct RemoteFetcher {
 25→    /// Request timeout.
 26→    timeout: Duration,
 27→    /// Cache directory for downloaded configs.
 28→    cache_dir: PathBuf,
 29→    /// HTTP client.
 30→    client: reqwest::blocking::Client,
 31→}
 32→
 33→impl RemoteFetcher {
 34→    /// Create a fetcher with the specified timeout.
 35→    pub fn new(timeout: Duration) -> Self {
 36→        let cache_dir = dirs::cache_dir()
 37→            .unwrap_or_else(|| PathBuf::from("~/.cache"))
 38→            .join("bivvy")
 39→            .join("remote-configs");
 40→
 41→        Self {
 42→            timeout,
 43→            cache_dir,
 44→            client: reqwest::blocking::Client::builder()
 45→                .timeout(timeout)
 46→                .build()
 47→                .expect("Failed to create HTTP client"),
 48→        }
 49→    }
 50→
 51→    /// Create a fetcher with a custom cache directory.
 52→    pub fn with_cache_dir(timeout: Duration, cache_dir: PathBuf) -> Self {
 53→        Self {
 54→            timeout,
 55→            cache_dir,
 56→            client: reqwest::blocking::Client::builder()
 57→                .timeout(timeout)
 58→                .build()
 59→                .expect("Failed to create HTTP client"),
 60→        }
 61→    }
 62→
 63→    /// Fetch a configuration file from a URL.
 64→    pub fn fetch(&self, url: &str) -> Result<String> {
 65→        // Check cache first
 66→        if let Some(cached) = self.check_cache(url)? {
 67→            return Ok(cached);
 68→        }
 69→
 70→        // Fetch from remote
 71→        let content = self.fetch_remote(url)?;
 72→
 73→        // Cache the result
 74→        self.save_cache(url, &content)?;
 75→
 76→        Ok(content)
 77→    }
 78→
 79→    /// Fetch a configuration file, bypassing cache.
 80→    pub fn fetch_fresh(&self, url: &str) -> Result<String> {
 81→        self.fetch_remote(url)
 82→    }
 83→
 84→    /// Fetch with authentication header.
 85→    pub fn fetch_with_auth(&self, url: &str, auth: &AuthHeader) -> Result<String> {
 86→        let response = self
 87→            .client
 88→            .get(url)
 89→            .header(&auth.header_name, &auth.header_value)
 90→            .send()
 91→            .with_context(|| format!("Failed to fetch {}", url))?;
 92→
 93→        if !response.status().is_success() {
 94→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
 95→        }
 96→
 97→        response
 98→            .text()
 99→            .with_context(|| format!("Failed to read response from {}", url))
100→    }
101→
102→    fn fetch_remote(&self, url: &str) -> Result<String> {
103→        let response = self
104→            .client
105→            .get(url)
106→            .send()
107→            .with_context(|| format!("Failed to fetch {}", url))?;
108→
109→        if !response.status().is_success() {
110→            return Err(anyhow!("HTTP {} fetching {}", response.status(), url));
111→        }
112→
113→        response
114→            .text()
115→            .with_context(|| format!("Failed to read response from {}", url))
116→    }
117→
118→    fn check_cache(&self, url: &str) -> Result<Option<String>> {
119→        let cache_path = self.cache_path(url);
120→        if cache_path.exists() {
121→            let content = std::fs::read_to_string(&cache_path)?;
122→            Ok(Some(content))
123→        } else {
124→            Ok(None)
125→        }
126→    }
127→
128→    fn save_cache(&self, url: &str, content: &str) -> Result<()> {
129→        let cache_path = self.cache_path(url);
130→        if let Some(parent) = cache_path.parent() {
131→            std::fs::create_dir_all(parent)?;
132→        }
133→        std::fs::write(&cache_path, content)?;
134→        Ok(())
135→    }
136→
137→    fn cache_path(&self, url: &str) -> PathBuf {
138→        use sha2::{Digest, Sha256};
139→        let mut hasher = Sha256::new();
140→        hasher.update(url.as_bytes());
141→        let hash = hex::encode(hasher.finalize());
142→        self.cache_dir.join(format!("{}.yml", hash))
143→    }
144→
145→    /// Clear the cache for a specific URL.
146→    pub fn clear_cache(&self, url: &str) -> Result<()> {
147→        let cache_path = self.cache_path(url);
148→        if cache_path.exists() {
149→            std::fs::remove_file(&cache_path)?;
150→        }
151→        Ok(())
152→    }
153→
154→    /// Clear all cached configurations.
155→    pub fn clear_all_cache(&self) -> Result<()> {
156→        if self.cache_dir.exists() {
157→            std::fs::remove_dir_all(&self.cache_dir)?;
158→        }
159→        Ok(())
160→    }
161→
162→    /// Get the request timeout.
163→    pub fn timeout(&self) -> Duration {
164→        self.timeout
165→    }
166→}
167→
168→impl Default for RemoteFetcher {
169→    fn default() -> Self {
170→        Self::new(Duration::from_secs(30))
171→    }
172→}
173→
174→/// Authentication header for remote fetching.
175→#[derive(Debug, Clone)]
176→pub struct AuthHeader {
177→    /// Header name (e.g., "Authorization").
178→    pub header_name: String,
179→    /// Header value (e.g., "Bearer token123").
180→    pub header_value: String,
181→}
182→
183→impl AuthHeader {
184→    /// Create a Bearer token auth header.
185→    pub fn bearer(token: &str) -> Self {
186→        Self {
187→            header_name: "Authorization".to_string(),
188→            header_value: format!("Bearer {}", token),
189→        }
190→    }
191→
192→    /// Create a custom header auth.
193→    pub fn custom(name: impl Into<String>, value: impl Into<String>) -> Self {
194→        Self {
195→            header_name: name.into(),
196→            header_value: value.into(),
197→        }
198→    }
199→}
200→
201→/// Resolves authentication from config settings.
202→pub fn resolve_auth(
203→    auth_type: &str,
204→    token_env: &str,
205→    header: Option<&str>,
206→    env_vars: &HashMap<String, String>,
207→) -> Option<AuthHeader> {
208→    // First check the provided env_vars map, then fall back to system env
209→    let token = env_vars
210→        .get(token_env)
211→        .cloned()
212→        .or_else(|| std::env::var(token_env).ok())?;
213→
214→    match auth_type {
215→        "bearer" => Some(AuthHeader::bearer(&token)),
216→        "header" => {
217→            let header_name = header.unwrap_or("X-Auth-Token");
218→            Some(AuthHeader::custom(header_name, &token))
219→        }
220→        _ => None,
221→    }
222→}
