//! Filesystem utilities.
//!
//! Provides atomic file operations to prevent corruption from
//! concurrent access.

use anyhow::{Context, Result};
use std::io::Write;
use std::path::Path;

/// Write content to a file atomically.
///
/// Writes to a temporary file in the same directory, then renames it to the
/// target path. On Unix, rename is atomic within the same filesystem, so
/// concurrent readers will see either the old complete file or the new
/// complete file — never a partial write.
pub fn atomic_write(path: &Path, content: &[u8]) -> Result<()> {
    let dir = path
        .parent()
        .ok_or_else(|| anyhow::anyhow!("path has no parent directory"))?;
    std::fs::create_dir_all(dir)?;

    let mut temp = tempfile::NamedTempFile::new_in(dir)
        .with_context(|| format!("Failed to create temp file in {dir:?}"))?;

    temp.write_all(content)
        .context("Failed to write to temp file")?;

    temp.persist(path)
        .with_context(|| format!("Failed to persist temp file to {path:?}"))?;

    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use std::sync::Arc;
    use tempfile::TempDir;

    #[test]
    fn writes_content_to_file() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test.txt");

        atomic_write(&path, b"hello world").unwrap();

        assert_eq!(std::fs::read_to_string(&path).unwrap(), "hello world");
    }

    #[test]
    fn overwrites_existing_file() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("test.txt");

        atomic_write(&path, b"first").unwrap();
        atomic_write(&path, b"second").unwrap();

        assert_eq!(std::fs::read_to_string(&path).unwrap(), "second");
    }

    #[test]
    fn creates_parent_directories() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("a").join("b").join("test.txt");

        atomic_write(&path, b"nested").unwrap();

        assert_eq!(std::fs::read_to_string(&path).unwrap(), "nested");
    }

    #[test]
    fn concurrent_writes_never_produce_partial_content() {
        let temp = TempDir::new().unwrap();
        let path = temp.path().join("shared.txt");

        atomic_write(&path, b"initial").unwrap();

        let barrier = Arc::new(std::sync::Barrier::new(8));
        let valid_values: Vec<String> = (0..4)
            .map(|i| format!("content-from-writer-{i}-with-padding-to-increase-size"))
            .collect();

        // 4 writer threads
        let writer_handles: Vec<_> = (0..4)
            .map(|i| {
                let path = path.clone();
                let barrier = barrier.clone();
                let content = valid_values[i].clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    for _ in 0..50 {
                        atomic_write(&path, content.as_bytes()).unwrap();
                    }
                })
            })
            .collect();

        // 4 reader threads
        let reader_handles: Vec<_> = (0..4)
            .map(|_| {
                let path = path.clone();
                let barrier = barrier.clone();
                let valid = valid_values.clone();
                std::thread::spawn(move || {
                    barrier.wait();
                    for _ in 0..50 {
                        if let Ok(content) = std::fs::read_to_string(&path) {
                            assert!(
                                content == "initial" || valid.contains(&content),
                                "Corrupted content: {content:?}"
                            );
                        }
                    }
                })
            })
            .collect();

        for h in writer_handles {
            h.join().unwrap();
        }
        for h in reader_handles {
            h.join().unwrap();
        }
    }
}

